import attr
from typing import Optional, List


@attr.s(cmp=False)
class SshServiceDetails(object):
    """

    :param str addr: IP ADDRESS or FQDN
    :param str username:
    :param Optional[int] port: Port number, default equals '22'
    :param Optional[str] password:
    :param Optional[str] private_key:
    :param Optional[SshServiceDetails] proxy:
    """
    addr = attr.ib(type=str)
    username = attr.ib(type=str)
    port = attr.ib(default=22, type=Optional[int])
    password = attr.ib(default=None, type=Optional[str])
    private_key = attr.ib(default=None, type=Optional[str])
    proxy = attr.ib(default=None, type=Optional["SshServiceDetails"])

    def __taf_contract_ssh__(self):
        return {
            "addr": self.addr,
            "username": self.username,
            "port": self.port,
            "password": self.password,
            "private_key": self.private_key,
            "proxy": (
                self.proxy.__taf_contract_ssh__() if self.proxy is not None else None
            )
        }


