class SCRadioConnectionDetails(object):
    def __init__(self, ssh_connection_details, telnet_connection_details):
        # type: (SshServiceDetails, TelnetConnectionDetails) -> None
        """

        :param SshServiceDetails ssh_connection_details:
        :param TelnetConnectionDetails telnet_connection_details:
        """
        self.ssh = ssh_connection_details
        self.telnet = telnet_connection_details

    def __taf_contract_ssh__(self):
        return self.ssh.__taf_contract_ssh__()


