@attr.s(cmp=False)
class IperfDataTransferIperfOptions(object):
    """
    This class is related to the ipef cli arguments

    :param Optional[int] parallel_streams: Sets the value of parallel streams argument -P in iperf command
    :param Optional[str] packet: Sets the value of packet argument -l in iperf command
    :param Optional[str] buffer: Sets the value of buffer argument -w in iperf command
    :param Optional[int] ttl: Sets the value of ttl argument -T in iperf command
    :param Optional[int] max_segment_size: Sets the value of max_segment_size argument -M in iperf command
    :param Optional[str] linux_congestion: Sets the value of linux_congestion argument -Z in iperf command
    :param Optional[str] data_file: Sets the input path of iperf client argument -F in iperf command
    :param Optional[str] output_file: Sets the output path of iperf server argument -F in iperf command
    :param Optional[dict] qci ports e.g. qci={1:60000, 2:60001},
        Sets the value of port argument -p in iperf command, defined per qci
    :param Optional[bool] enhanced_reports: Sets the iperf server and iperf client argument -e in iperf commands
    """
    parallel_streams = attr.ib(default=None, type=Optional[int])
    packet = attr.ib(default=None, type=Optional[str])
    buffer = attr.ib(default=None, type=Optional[str])
    ttl = attr.ib(default=None, type=Optional[int])
    max_segment_size = attr.ib(default=None, type=Optional[int])
    linux_congestion = attr.ib(default=None, type=Optional[str])
    data_file = attr.ib(default=None, type=Optional[str])
    output_file = attr.ib(default=None, type=Optional[str])
    qci = attr.ib(default=None, type=Optional[dict])
    enhanced_reports = attr.ib(default=None, type=Optional[bool])


@attr.s(cmp=False)
class IperfDataTransferDetails(object):
    """
    :param SshServiceDetails ssh_connection_details: depending on the host,
    if it is in UE entity, this field represents UE control PC, if it is in AppServer
    Entity, this field represents AppServer
    :param str network_interface_address: IP of interface used for data transfer
    :param str network_interface_name: name of interface used for data transfer
    :param str iperf_path: path to iperf binary, used to start the process
    :param int port: port for traffic service
    :param list ports: ports for traffic service. Sometimes, the ports of the appserver are static,
    configured by real core for special port assignment rule or specific qci
    :param Optional[bool] iperf_bind_ue_ip:  parameter to trigger or not binding to ue ip in uplink data transfer,
    True used by default, False to not use binding
    :param Optional[str] iperf_mode: use 'adb' value here for Askey Ues (SDX55/60 which can work with at commands and adb
    if you want to run iperf from android adb instead to ue pc
    :param Optional[str] serial_number: to be set when 'iperf_mode' is used, this is the sn of ue visible under 'adb devices'
    :param Optional[int] iperf_interval: Iperf interval in seconds (default: 1)
    :param Optional[int] server_close_delay: Delay in closing iperf server in case of delay between client ans server hosts in seconds
    :param Optional[str] traffic_type: parameter to specify the type of traffic,
    some behaviour differs for 'nbiot' traffic type
    :param Optional[IperfDataTransferIperfOptions] iperf_options: options used in iperf command directly
    :param Optional[PingDetails] ping: ping attributes like ip to ping, number of requests, allowed packets loss
    :param Optional[int] iperf_version: parameter to specify iperf version on which data transfer has to be started,
    possible values: 3 to use iperf3, 2 to use iperf2, if not set iperf2 is used by default
    """
    ssh_connection_details = attr.ib(type=SshServiceDetails)
    network_interface_address = attr.ib(default=None, type=Optional[str])
    network_interface_name = attr.ib(default=None, type=Optional[str])
    iperf_path = attr.ib(default=None, type=Optional[str])
    port = attr.ib(default=None, type=Optional[int])
    ports = attr.ib(default=None, type=Optional[List[int]])
    iperf_mode = attr.ib(default=None, type=Optional[str])
    serial_number = attr.ib(default=None, type=Optional[str])
    iperf_interval = attr.ib(default=None, type=Optional[int])
    server_close_delay = attr.ib(default=None, type=Optional[int])
    iperf_bind_ue_ip = attr.ib(default=None, type=Optional[bool])
    traffic_type = attr.ib(default=None, type=Optional[str])
    iperf_options = attr.ib(default=None, type=IperfDataTransferIperfOptions)
    ping = attr.ib(default=None, type=PingDetails)
    iperf_version = attr.ib(default=None, type=Optional[int])

    def __attrs_post_init__(self):
        self.ports = self._get_ports(self.port, self.ports)

    @staticmethod
    def _get_ports(port, ports):
        return ports or ([port] if port else None)

    def __taf_contract_ssh__(self):
        return self.ssh_connection_details.__taf_contract_ssh__()


